import os,json,base64,hashlib
from pathlib import Path
files=json.loads('{"triangle_pixels.py": "", "triangle_display.py": "", "card.json": "", "authorization.json": "", "source.bin": ""}')
root=Path('/home/gama/sgx535-display-FIRE3-20261006-tools')
assert not Path('/home/gama/sgx535-display-FIRE3-20261006-evidence').exists(), 'evidence destination already exists'
root.mkdir(mode=0o700,exist_ok=False)
receipt={}
for name,encoded in files.items():
 data=base64.b64decode(encoded,validate=True);path=root/name
 fd=os.open(path,os.O_CREAT|os.O_EXCL|os.O_WRONLY|os.O_NOFOLLOW,0o600)
 try:
  with os.fdopen(fd,'wb',closefd=False) as f:f.write(data);f.flush();os.fsync(fd)
 finally:os.close(fd)
 assert path.read_bytes()==data
 receipt[name]={'bytes':len(data),'sha256':hashlib.sha256(data).hexdigest()}
fd=os.open(root,os.O_DIRECTORY|os.O_RDONLY);os.fsync(fd);os.close(fd)
print(json.dumps({'deployment':str(root),'verified_files':receipt,'display_mutations':0,'sgx_invocations':0},indent=2))
